ledger, seen = [], {}
failures = [True, True, False]       # the network fails twice, then works

def charge(key, amount):
    if failures.pop(0):
        raise ConnectionError("timeout")
    if key not in seen:
        ledger.append(amount)
        seen[key] = f"charged {amount}"
    return seen[key]

delays = []
for attempt in range(1, 5):
    try:
        receipt = charge("order-7-charge", 250)
        break
    except ConnectionError:
        delays.append(0.1 * 2 ** (attempt - 1))   # would wait this long

failures.append(False)
again = charge("order-7-charge", 250)         # same key: no second charge
print(receipt, "| waits:", delays, "| ledger:", ledger, "|", again)
